using System;using System.Collections.Generic;using UnityEngine;
// Stable grid analysis. It never writes geometry, entities, encounter weights or save data.
public static class DungeonDecorationPlanner {
 public static readonly Vector2Int[] Directions={Vector2Int.up,Vector2Int.right,Vector2Int.down,Vector2Int.left};
 static uint Hash(string text){uint h=2166136261;foreach(char c in text){h^=c;h*=16777619;}return h;}
 static float Roll(string key){return (Hash(key)&0xffffff)/16777216f;}
 public static bool Protected(DungeonMapSettings map,Vector2Int cell){if((cell-map.startCell).sqrMagnitude<=2)return true;if(map.entities!=null)foreach(var e in map.entities.objects){if(e==null)continue;int radius=e.kind==DungeonEntityKind.NPC||e.kind==DungeonEntityKind.Savepoint||e.kind==DungeonEntityKind.Teleport?2:1;if(Mathf.Abs(cell.x-e.cell.x)+Mathf.Abs(cell.y-e.cell.y)<=radius)return true;if(e.kind==DungeonEntityKind.Door&&cell==e.cell+Directions[e.heading])return true;}
  var regions=map.regions!=null?map.regions:map.includeLegacyObjects?DungeonRegionSettings.Current:null;if(regions!=null)foreach(var e in regions.placedEnemies)if(e!=null&&e.enabled&&Mathf.Abs(cell.x-e.cell.x)+Mathf.Abs(cell.y-e.cell.y)<=2)return true;
  if(map.includeLegacyObjects&&RefugeSettings.Current!=null){var r=RefugeSettings.Current;foreach(var n in r.npcs)if((cell-n.cell).sqrMagnitude<=8)return true;foreach(var n in r.nodes)if((cell-n.cell).sqrMagnitude<=8)return true;if((cell-r.saveCell).sqrMagnitude<=8||(cell-r.startCell).sqrMagnitude<=2)return true;var doors=new[]{r.exitDoorCell,map.legacyExitDoorCell,PreservationCorridorSettings.Current!=null?PreservationCorridorSettings.Current.secondDoorCell:map.legacyExitDoorCell};foreach(var d in doors)if(Vector2.Distance(cell,d)<=2)return true;}return false;
 }
 public static bool IsWall(DungeonMapSettings map,Vector2Int cell){return cell.x>=0&&cell.y>=0&&cell.y<map.rows.Length&&cell.x<map.rows[0].Length&&map.rows[cell.y][cell.x]=='#';}
 public static int WallHeading(DungeonMapSettings map,Vector2Int cell){int torch=-1;if((cell.x+cell.y)%3==2&&cell!=new Vector2Int(9,8))for(int h=0;h<4;h++)if(!map.IsFloor(cell+Directions[h])){torch=h;break;}for(int h=0;h<4;h++)if(h!=torch&&IsWall(map,cell+Directions[h]))return h;return -1;}
 public static string InvalidReason(DungeonMapSettings map,DungeonDecorationPlacement p,DungeonDecorationDefinition def){if(def==null||def.prefab==null)return "Falta prefab del catálogo";if(!map.IsFloor(p.cell))return "Debe anclarse en una casilla de suelo";if(p.scale<.25f||p.scale>1.5f||p.localOffset.sqrMagnitude>1)return "Escala u offset fuera del margen seguro";float cell=EnemySpaceLayout.Corridor(DungeonVisualSettings.Current,EnemySizeSettings.Current).x;if((def.mount==DecorationMount.Wall||def.mount==DecorationMount.Room)&&Mathf.Max(0,p.localOffset.z)+def.depth*Mathf.Clamp(cell/3,1,1.25f)*p.scale>cell*.5f-.65f)return "Invade el espacio libre del pasillo";if(def.mount==DecorationMount.Door){return map.entities!=null&&map.entities.objects.Exists(e=>e.kind==DungeonEntityKind.Door&&e.cell==p.cell&&e.heading==p.heading)?null:"Debe coincidir con una puerta del mapa";}if(Protected(map,p.cell))return "Demasiado cerca de un interactivo, enemigo manual o inicio";if((def.mount==DecorationMount.Wall||def.mount==DecorationMount.Room)&&!IsWall(map,p.cell+Directions[p.heading]))return "La orientación debe apuntar a una pared";if((def.mount==DecorationMount.Wall||def.mount==DecorationMount.Room)&&(p.cell.x+p.cell.y)%3==2&&p.cell!=new Vector2Int(9,8)){for(int h=0;h<4;h++)if(!map.IsFloor(p.cell+Directions[h])){if(h==p.heading)return "Esta pared ya tiene una antorcha";break;}}return null;}
 static bool Occupied(List<DungeonDecorationPlacement> items,DungeonDecorationPlacement p,DungeonDecorationCatalog catalog){foreach(var old in items){var a=catalog.Find(old.prefabId);var b=catalog.Find(p.prefabId);if(old.cell==p.cell&&a!=null&&b!=null&&a.mount==b.mount&&(a.mount!=DecorationMount.Wall||old.heading==p.heading))return true;}return false;}
 public static List<DungeonDecorationPlacement> Build(DungeonMapSettings map){var result=new List<DungeonDecorationPlacement>();var settings=map.decorations;if(settings==null||!settings.enabled||settings.Catalog==null)return result;var catalog=settings.Catalog;var ids=new HashSet<string>();foreach(var p in settings.placements)if(p!=null&&p.enabled&&!string.IsNullOrEmpty(p.id)&&ids.Add(p.id)&&InvalidReason(map,p,catalog.Find(p.prefabId))==null&&!Occupied(result,p,catalog))result.Add(p);if(!settings.automaticEnabled)return result;
  var regions=settings.regions!=null?settings.regions:map.regions!=null?map.regions:map.includeLegacyObjects?DungeonRegionSettings.Current:null;int added=0;var used=new List<Vector2Int>();
  for(int y=0;y<map.rows.Length;y++)for(int x=0;x<map.rows[y].Length;x++){if(added>=settings.maximumAutomatic)break;var cell=new Vector2Int(x,y);if(!map.IsFloor(cell)||Protected(map,cell))continue;var region=regions!=null?regions.At(cell):null;string zone=region!=null?region.id:"default";var rule=settings.zones.Find(r=>r.zoneId==zone);if(rule!=null&&!rule.enabled)continue;float density=rule!=null?rule.density:settings.density;var theme=rule!=null?rule.theme:region!=null&&region.safeArea?DecorationTheme.Safe:DecorationTheme.General;string key=settings.seed+":"+zone+":"+x+":"+y;
   if(density<=0||Roll(key+":density")>density)continue;bool nearby=false;foreach(var old in used)if(Mathf.Abs(old.x-x)+Mathf.Abs(old.y-y)<settings.minimumSpacing){nearby=true;break;}if(nearby)continue;
   int walls=0,heading=WallHeading(map,cell);for(int h=0;h<4;h++)if(IsWall(map,cell+Directions[h])){walls++;}
   bool corner=false;for(int h=0;h<4;h++)if(IsWall(map,cell+Directions[h])&&IsWall(map,cell+Directions[(h+1)%4]))corner=true;int floorAround=0;for(int yy=-1;yy<=1;yy++)for(int xx=-1;xx<=1;xx++)if(map.IsFloor(cell+new Vector2Int(xx,yy)))floorAround++;bool room=floorAround>=6;
   var candidates=new List<DungeonDecorationDefinition>();float total=0;foreach(var d in catalog.entries){if(d==null||d.prefab==null||d.weight<=0||d.mount==DecorationMount.Door||d.theme!=DecorationTheme.General&&d.theme!=theme||d.cornerOnly&&!corner||d.mount==DecorationMount.Room&&(!room||heading<0)||(d.mount==DecorationMount.Wall&&heading<0))continue;candidates.Add(d);total+=d.weight*(room&&d.mount==DecorationMount.Room?settings.roomAccentWeight:1);}if(total<=0)continue;float pick=Roll(key+":kind")*total;var chosen=candidates[candidates.Count-1];foreach(var d in candidates){pick-=d.weight*(room&&d.mount==DecorationMount.Room?settings.roomAccentWeight:1);if(pick<=0){chosen=d;break;}}
   var p=new DungeonDecorationPlacement{id="auto:"+zone+":"+x+":"+y,prefabId=chosen.id,cell=cell,heading=Mathf.Max(0,heading)};if(settings.suppressedAutomaticIds.Contains(p.id)||Occupied(result,p,catalog)||InvalidReason(map,p,chosen)!=null)continue;result.Add(p);used.Add(cell);added++;
  }
  if(map.entities!=null)foreach(var e in map.entities.objects)if(e.kind==DungeonEntityKind.Door&&added<settings.maximumAutomatic){var region=regions!=null?regions.At(e.cell):null;string zone=region!=null?region.id:"default";var rule=settings.zones.Find(r=>r.zoneId==zone);if(rule!=null&&!rule.enabled||(rule!=null?rule.density:settings.density)<=0)continue;var frame=Array.Find(catalog.entries,d=>d!=null&&d.mount==DecorationMount.Door);if(frame==null)continue;var p=new DungeonDecorationPlacement{id="auto:door:"+e.id,prefabId=frame.id,cell=e.cell,heading=e.heading};if(!settings.suppressedAutomaticIds.Contains(p.id)&&!Occupied(result,p,catalog)){result.Add(p);added++;}}
  return result;
 }
}
